import{_ as s,o as n,c as e,ai as l}from"./chunks/framework.Ba-VnP44.js";const o=JSON.parse('{"title":"交付追踪与回滚","description":"","frontmatter":{},"headers":[],"relativePath":"ai/productivity/dev-spec/03-quality/delivery-rollback.md","filePath":"ai/productivity/dev-spec/03-quality/delivery-rollback.md"}'),i={name:"ai/productivity/dev-spec/03-quality/delivery-rollback.md"};function t(p,a,r,d,c,b){return n(),e("div",null,[...a[0]||(a[0]=[l(`<h1 id="交付追踪与回滚" tabindex="-1">交付追踪与回滚 <a class="header-anchor" href="#交付追踪与回滚" aria-label="Permalink to “交付追踪与回滚”">​</a></h1><blockquote><p>第三层 · 质量保障。解决「交付后能不能追溯、出问题能不能回滚」——用交付报告留痕，用回滚方案兜底，让每次改动都可进可退。</p></blockquote><h2 id="贯穿全流程的定位" tabindex="-1">贯穿全流程的定位 <a class="header-anchor" href="#贯穿全流程的定位" aria-label="Permalink to “贯穿全流程的定位”">​</a></h2><p>追踪和回滚的意识要从改动前就有，不是出问题才想：</p><table tabindex="0"><thead><tr><th>时机</th><th>要做什么</th></tr></thead><tbody><tr><td>改动前</td><td>记录起始状态（分支、提交、未提交改动）</td></tr><tr><td>开发中</td><td>每轮提交，形成可回退的粒度</td></tr><tr><td>交付时</td><td>交付报告留痕，写清改了什么、证据、遗留</td></tr><tr><td>交付后</td><td>出问题能按提交定位、按方案回滚</td></tr></tbody></table><h2 id="核心内容" tabindex="-1">核心内容 <a class="header-anchor" href="#核心内容" aria-label="Permalink to “核心内容”">​</a></h2><h3 id="交付追踪" tabindex="-1">交付追踪 <a class="header-anchor" href="#交付追踪" aria-label="Permalink to “交付追踪”">​</a></h3><p>交付报告是追溯的核心。最少记录：</p><ul><li>任务、级别、修改范围、不做项执行情况。</li><li>修改文件清单（改了什么、为什么）。</li><li>验证证据（命令与输出关键行）。</li><li>安全检查结论。</li><li>遗留问题（是什么、影响、建议、谁决定）。</li><li>本次沉淀去向。</li></ul><p>遗留问题必须有去处：建待办、写进认知资料，或在报告里留痕并有人负责。「下次再说」不算处理。</p><h3 id="回滚方案" tabindex="-1">回滚方案 <a class="header-anchor" href="#回滚方案" aria-label="Permalink to “回滚方案”">​</a></h3><p>复杂改动（涉及数据结构、接口契约、多文件、数据库迁移）在方案阶段就要写回滚方案：</p><table tabindex="0"><thead><tr><th>项</th><th>内容</th></tr></thead><tbody><tr><td>回滚触发条件</td><td>什么情况下必须回滚</td></tr><tr><td>回滚粒度</td><td>按哪个提交 / 哪个阶段回退</td></tr><tr><td>数据回滚</td><td>迁移能否逆执行，数据能否恢复</td></tr><tr><td>兼容性兜底</td><td>新旧版本能否并存，是否需要开关</td></tr><tr><td>回滚后验证</td><td>回到什么状态算回滚成功</td></tr></tbody></table><p><strong>不是所有改动都要真回滚</strong>。有时前滚修复更快，但要先判断，不默认硬扛。</p><h3 id="出问题后的处理顺序" tabindex="-1">出问题后的处理顺序 <a class="header-anchor" href="#出问题后的处理顺序" aria-label="Permalink to “出问题后的处理顺序”">​</a></h3><ol><li>复现并固定证据（见 <a href="/my-vitepress-site/ai/productivity/dev-spec/02-lifecycle/bugfix.html">06 逻辑与 BUG 修复</a>）。</li><li>判断是前滚修复还是回滚——看改动范围、数据影响、时间成本。</li><li>按回滚方案执行，保护未涉及的改动。</li><li>回滚后验证，确认回到可用状态。</li><li>在交付报告里记录这次事故和处理方式。</li></ol><h3 id="git-层的可回退性" tabindex="-1">Git 层的可回退性 <a class="header-anchor" href="#git-层的可回退性" aria-label="Permalink to “Git 层的可回退性”">​</a></h3><ul><li>每轮子任务一次提交，粒度够细才能精确回退。</li><li>提交信息说清改了什么，方便定位。</li><li>不擅自 <code>reset --hard</code>、强推、删分支（见 <a href="/my-vitepress-site/ai/productivity/dev-spec/03-quality/git-version.html">Git 与版本管理</a>）。</li></ul><h2 id="可复制提示词" tabindex="-1">可复制提示词 <a class="header-anchor" href="#可复制提示词" aria-label="Permalink to “可复制提示词”">​</a></h2><details><summary><strong>生成回滚方案</strong></summary><div class="language-text line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>请为下面这次改动生成回滚方案，本轮只输出方案，不执行。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>改动内容：&lt;描述&gt;</span></span>
<span class="line"><span>涉及范围：&lt;文件 / 接口 / 数据表 / 迁移&gt;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>请按以下结构输出：</span></span>
<span class="line"><span>1. 回滚触发条件：什么情况下必须回滚。</span></span>
<span class="line"><span>2. 回滚粒度：按哪个提交或阶段回退，列出相关提交。</span></span>
<span class="line"><span>3. 数据回滚：迁移是否可逆向，数据如何恢复，是否有丢失风险。</span></span>
<span class="line"><span>4. 兼容性兜底：新旧版本能否并存，是否需要开关。</span></span>
<span class="line"><span>5. 回滚步骤：按顺序写清每一步，标出需要人确认的操作。</span></span>
<span class="line"><span>6. 回滚后验证：怎么确认回到了可用状态。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>无法回滚的部分明确标出，并说明替代处理方式（比如只能前滚修复）。</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br></div></div></details><details><summary><strong>交付追溯自查</strong></summary><div class="language-text line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>请检查下面这份交付报告是否足以支撑后续追溯，只输出检查结果。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>报告：&lt;粘贴&gt;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>检查项：</span></span>
<span class="line"><span>1. 能否看清改了哪些文件、为什么改。</span></span>
<span class="line"><span>2. 验证结果是否有命令和输出证据，四态是否分清。</span></span>
<span class="line"><span>3. 遗留问题是否逐条列出、有人负责、有去处。</span></span>
<span class="line"><span>4. 是否记录了用户已有改动的处理情况。</span></span>
<span class="line"><span>5. 复杂改动是否有回滚方案或回滚说明。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>每项给「满足 / 缺失 + 需要补什么」。最后判断：如果三个月后出问题，靠这份报告能不能定位到这次改动。</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br></div></div></details><h2 id="验收要点" tabindex="-1">验收要点 <a class="header-anchor" href="#验收要点" aria-label="Permalink to “验收要点”">​</a></h2><ul><li>[ ] 复杂改动在方案阶段就有回滚方案。</li><li>[ ] 每轮提交粒度细，提交信息可定位。</li><li>[ ] 交付报告完整，遗留问题有去处、有人负责。</li><li>[ ] 回滚方案写清触发条件、粒度、数据、验证。</li><li>[ ] 出问题时能按提交定位、按方案回退。</li></ul><p>到这里，三层体系完整闭环：<strong>第一层</strong>提供能力，<strong>第二层</strong>规范过程，<strong>第三层</strong>全程保障。整套规范的价值不在页数，而在每次开发都能少问、少错、可追溯。</p>`,24)])])}const u=s(i,[["render",t]]);export{o as __pageData,u as default};
